ck=DockStyle.Fill,Font=Theme.Font(10,FontStyle.Regular),LinkColor=Theme.Muted,ActiveLinkColor=Theme.Accent,TextAlign=ContentAlignment.MiddleCenter};explain.LinkClicked+=delegate{ShowTextDetails("会检查什么？","先看看这台电脑有没有网络连接，再试常用网站和 AI 服务有没有回应。\r\n\r\n收到回应不代表账号已经登录、应用功能全都正常，或 AI 一定能生成答案。\r\n\r\n这次不会直接测出宽带最高速度，也不能凭空知道别的设备用了多少网。下方每项说明可以展开。\r\n\r\n自动 AI 开启时，完成检查后会把匿名摘要交给已登录的 Codex，消耗共享额度；可在 AI 页面随时暂停。");};actionArea.Controls.Add(explain,0,2);layout.Controls.Add(actionArea,2,0);hero.Controls.Add(layout);Add(p,hero,222);var tools=new TableLayoutPanel{ColumnCount=3,RowCount=1,BackColor=Theme.Back};for(int i=0;i<3;i++)tools.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33.333f));string[] toolText={"↓  看电脑用了多少网","▦  认识设备和程序","✦  让 AI 解释原因"};int[] destinations={0,4,6};for(int i=0;i<3;i++){int target=destinations[i];var button=ButtonText(toolText[i],false);((RoundedButton)button).Borderless=true;button.BackColor=Theme.Back;button.ForeColor=Theme.Text;button.Dock=DockStyle.Fill;button.Font=Theme.Font(11,FontStyle.Regular);button.Margin=new Padding(0,0,i==2?0:10,0);button.Click+=delegate{SelectPage(target);};tools.Controls.Add(button,i,0);}Add(p,tools,50);var heading=LabelText("检查结果",13,Theme.Text,true);Add(p,heading,32);var hint=LabelText("点每行右侧的 ＋，看看为什么这样判断、接下来怎么查。",10,Theme.Muted,false);Add(p,hint,28);var answers=new TableLayoutPanel{ColumnCount=1,RowCount=6,BackColor=Theme.Card};answers.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));string[] questions={"现在网络怎么了？","哪里可能不通？","网速正常吗？","别的设备在占网吗？","哪个程序在用网？","我该怎么办？"};string[] actions={"看网站结果","看 AI 建议","测一下速度","看设备","看程序","看下一步"};for(int i=0;i<6;i++){int index=i;var row=new InspectionRow(i+1,questions[i]){Dock=DockStyle.Fill};answerHeadlines[i]=row.Headline;answerDetails[i]=row.Detail;answerDetails[i].Text="检查后会说明已经知道什么，以及怎样继续查。";row.ActionButton.Text=actions[i];row.ActionButton.Click+=async delegate{if(index==0)SelectPage(0);else if(index==1||index==5)SelectPage(6);else if(index==2){if(!row.Expanded)row.ToggleExpanded();await RunSpeedCheck();}else{SelectPage(4);if(index==4)ScrollToProcessTools();}};answers.RowStyles.Add(new RowStyle(SizeType.Absolute,78));answers.Controls.Add(row,0,i);row.ExpandedChanged+=delegate{answers.RowStyles[index].Height=row.Expanded?140:78;var stack=answers.Parent as TableLayoutPanel;if(stack!=null)stack.RowStyles[stack.GetRow(answers)].Height=answers.RowStyles.Cast<RowStyle>().Sum(x=>x.Height)+16;};}Add(p,answers,468);findingsGrid=Grid(false);Col(findingsGrid,"level","需要留意吗",110);Col(findingsGrid,"title","发现了什么",250);Col(findingsGrid,"evidence","可见证据",280);Col(findingsGrid,"advice","可以先怎么做",330);Col(findingsGrid,"confidence","把握",80);findingsGrid.CellDoubleClick+=delegate(object sender,DataGridViewCellEventArgs e){if(e.RowIndex>=0)ShowFindingDetails(findingsGrid.Rows[e.RowIndex].Tag as Finding);};AddTechnical(p,TitledBox("这轮检查的完整记录 · 双击展开说明",findingsGrid),310);speedStatus.Text="尚未做下载测试。电脑当时的用量，不等于宽带最高速度。";speedStatus.ForeColor=Theme.Muted;speedStatus.Font=Theme.Font(10,FontStyle.Regular);speedStatus.Padding=new Padding(14);speedStatus.BackColor=Theme.Card;AddTechnical(p,speedStatus,110);}
  void ScrollToProcessTools(){if(processStatusLabel==null||processStatusLabel.Parent==null)return;var point=pages[4].PointToClient(processStatusLabel.Parent.PointToScreen(processStatusLabel.Location));pages[4].AutoScrollPosition=new Point(0,Math.Max(0,point.Y-pages[4].AutoScrollPosition.Y-125));}
  void RefreshCheckHero(){if(checkHeadline==null)return;var frame=controller.CurrentFrame;var measured=frame==null?new List<ProbeResult>():frame.Probes.Where(x=>x.Outcome!="Skipped").ToList();int unanswered=measured.Count(x=>!x.StatusCode.HasValue||x.StatusCode==407);bool busy=controller.IsProbing;mainCheckButton.Enabled=!busy;mainCheckButton.Text=busy?"正在检查…":frame==null?"立即检查":"再检查一次";checkOrb.State=busy?"busy":frame==null||measured.Count==0?"idle":unanswered==0?"good":"attention";checkOrb.Caption=busy?"正在检查":frame==null?"待检查":measured.Count==0?"还判断不了":unanswered==0?measured.Count+" 项有回应":unanswered+" 项需留意";checkHeadline.Text=busy?"正在看看哪里卡住了":frame==null?"上网不顺？\n看看哪里卡住了":measured.Count==0?"这次还没查清楚":unanswered==0?"这次 "+measured.Count+" 个网站\n都有回应":"有 "+unanswered+" 项\n暂时没有回应";checkStatus.Text=busy?"正在等待常用网站和 AI 服务的回应，请稍候。":frame==null?"先检查电脑连接、常用网站和 AI 服务。":measured.Count==0?"没有取得有效结果，等这一轮结束后可以再试。":"完成于 "+frame.At.ToLocalTime().ToString("HH:mm:ss")+" · 有回应不代表所有应用功能都正常。";checkOrb.Invalidate();}
  async Task RunSpeedCheck(){if(speedCheckRunning)return;speedCheckRunning=true;speedStatus.Text="正在下载一小段测试内容，请稍候…";RefreshPlainAnswers();try{lastSpeedTest=await controller.RunSpeedTestAsync();lastSpeedAt=DateTime.Now;var r=lastSpeedTest;speedStatus.Text=String.IsNullOrWhiteSpace(r.Error)?String.Format("这次小样本下载约 {0:0.00} Mbps，用了 {1:0.00} MiB 流量、{2:0.0} 秒。\n它只反映这一次测试，不是宽带最高速度，也不能单独判断所有应用。",r.Mbps,r.Bytes/1048576.0,r.Seconds):"这次测速没完成："+FriendlyText(r.Error);}catch(Exception ex){speedStatus.Text="这次测速没完成："+FriendlyText(ex.Message);lastSpeedTest=new SpeedTestResult{Error=ex.Message};}finally{speedCheckRunning=false;RefreshData(true);}}
  string FriendlyText(string value){return(value??"").Replace("HTTP","服务回应").Replace("DNS","查找网站地址").Replace("TCP","建立连接").Replace("网关","路由器").Replace("代理","中转工具").Replace("探测","检查").Replace("传输失败率","没收到回应的比例");}
  void ShowFindingDetails(Finding finding){if(finding==null)return;ShowTextDetails("完整检查说明",finding.Title+"\r\n时间："+Theme.LocalTime(finding.At)+"\r\n\r\n实际记录：\r\n"+finding.Evidence+"\r\n\r\n建议：\r\n"+finding.Advice+"\r\n\r\n判断把握："+finding.Confidence);}
  string HumanStatus(ProbeResult r){if(r==null)return"还没有检查";if(r.Outcome=="Skipped")return"这次没测到，稍后再试";if(r.StatusCode==407)return"上网通道要求先登录";if(r.StatusCode==401||r.StatusCode==403)return"服务有回应，账号未验证";if(r.StatusCode==404||r.StatusCode==405)return"地址有回应，功能未验证";if(r.StatusCode==429)return"服务要求稍后再试";if(r.StatusCode.HasValue&&r.StatusCode.Value>=500)return"服务回应了，但返回错误";if(r.StatusCode.HasValue)return"收到回应";return"暂时没等到回应";}
  string HumanMeaning(ProbeResult r){if(r.Outcome=="Skipped")return"本轮检查器忙，没有测量，不算网络故障。";if(r.StatusCode==407)return"中转连接要求登录，尚未收到目标网站的回应。";if(r.StatusCode==401||r.StatusCode==403)return"网络这一段有回应；还需要在应用里确认登录和使用权限。";if(r.StatusCode==404||r.StatusCode==405)return"当前地址能回应；具体功能能不能用，还需要在应用里试。";if(r.StatusCode==429)return"可能是请求太频繁或服务限制，等一会再试。";if(r.StatusCode.HasValue&&r.StatusCode.Value>=500)return"服务这次返回错误，建议重试并观察是否持续。";if(r.StatusCode.HasValue)return r.HttpMs.HasValue&&r.HttpMs.Value>2000?"这次回应较慢，但不代表应用一定卡顿。":"本次收到了回应；不代表账号和所有功能都已验证。";return"一次没回应还不能确定原因，可重试并结合其他服务一起看。";}
  void ShowServiceDetails(ProbeResult r){if(r==null)return;ShowTextDetails("服务技术详情 · "+r.Name,"先说结论："+HumanStatus(r)+"\r\n"+HumanMeaning(r)+"\r\n\r\n测量时间："+Theme.LocalTime(r.At)+"\r\nURL："+r.Url+"\r\nDNS："+Theme.Delay(r.DnsMs)+"\r\n直连 TCP："+Theme.Delay(r.TcpMs)+"\r\nHTTP："+Theme.Delay(r.HttpMs)+"\r\n状态："+(r.StatusCode.HasValue?r.StatusCode.ToString():"无状态码")+" / "+r.Outcome+"\r\n实际路径："+r.Route+"\r\n原始说明："+r.Error);}
  void BuildHistory(){var p=NewPage();var bar=Bar();bar.Controls.Add(LabelSized("时间范围",75));historyPeriod=Combo(110);foreach(var item in new[]{"最近 1 小时","最近 6 小时","最近 24 小时","最近 7 天","最近 30 天"})historyPeriod.Items.Add(item);historyPeriod.SelectedIndex=0;bar.Controls.Add(historyPeriod);bar.Controls.Add(LabelSized("曲线内容",75));historyMetric=Combo(250);bar.Controls.Add(historyMetric);RefreshHistoryChoices();historyPeriod.SelectedIndexChanged+=delegate{RefreshHistory();};historyMetric.SelectedIndexChanged+=delegate{RefreshHistory();};var export=ButtonText("导出 CSV",false);export.Click+=delegate{SaveDialog("CSV 数据|*.csv","NetScope-history.csv",delegate(string path){controller.ExportHistoryCsv(path,SelectedPeriod());});};bar.Controls.Add(export);Add(p,bar,48);Add(p,TitledBox("历史采样曲线 / 本地时间",historyChart),500);Note(p,"鼠标移到曲线可查看附近样本。未采样、暂停、程序退出或失败值会留空；长时间范围按画布宽度减少绘制点，原始记录仍可导出。流量曲线为 30 秒时间加权平均；桶内峰值保留在 CSV。服务曲线只显示当前 URL，网络与路径变更处断线。历史保留长度由「自定义」决定。",72);}
  void BuildAdapters(){var p=NewPage();adapterGrid=Grid(false);Col(adapterGrid,"name","连接名称",220);Col(adapterGrid,"state","连上了吗",100);Col(adapterGrid,"download","当前下载用量",140);Col(adapterGrid,"upload","当前上传用量",140);Col(adapterGrid,"kind","技术类型",150);Col(adapterGrid,"link","协商速率",130);Col(adapterGrid,"address","IP 地址",260);Add(p,TitledBox("这台电脑的网络连接",adapterGrid),350);routeBox=TextBoxDark(true);routeBox.ReadOnly=true;routeBox.Text="等待第一次检查。";AddTechnical(p,TitledBox("连接技术详情",routeBox),330);adapterGrid.SelectionChanged+=delegate{RefreshAdapterDetail();};var button=ButtonText("查看所选连接的技术详情",false);button.Width=235;button.Click+=delegate{RefreshAdapterDetail();ShowTextDetails("连接技术详情",routeBox.Text);};var bar=Bar();bar.Controls.Add(button);Add(p,bar,58);Note(p,"有些连接由 VPN 或中转工具创建，同一份流量可能被重复统计。若数字不符合预期，可在“我的设置”里选择你实际使用的连接。",65);}
  void BuildDevices(){var p=NewPage();var bar=Bar();discoveryButton=ButtonText("找一找设备",true);discoveryButton.Width=165;discoveryButton.Click+=async delegate{if(controller.IsDeviceDiscovering){controller.CancelDeviceDiscovery();return;}try{await controller.DiscoverLocalDevicesAsync();lastDeviceCardsKey="";RefreshDevices();}catch(Exception ex){ShowError(ex);}finally{RefreshDiscoveryUi();}};bar.Controls.Add(discoveryButton);var refresh=ButtonText("刷新已有记录",false);refresh.Width=150;refresh.Click+=async delegate{refresh.Enabled=false;try{await LoadDeviceRecordsAsync(true);}catch(Exception ex){ShowError(ex);}finally{refresh.Enabled=true;}};bar.Controls.Add(refresh);var import=ButtonText("导入路由器记录",false);import.Width=175;import.Click+=delegate{using(var d=new OpenFileDialog{Title="导入路由器导出的设备用网记录",Filter="CSV 文件|*.csv"}){if(d.ShowDialog(this)==DialogResult.OK){try{controller.ImportGatewayCsv(d.FileName);RefreshDevices();deviceSummary.Text="已导入。这些用量属于文件记录的时刻，不会自动变成实时数据。";}catch(Exception ex){ShowError(ex);}}}};bar.Controls.Add(import);var more=ButtonText("更多工具  ▾",false);more.Width=140;var menu=new ContextMenuStrip{Font=Theme.Font(10,FontStyle.Regular)};AddDeviceMenuAction(menu,"尝试认出名字",delegate{return controller.ResolveDeviceNamesAsync();});AddDeviceMenuAction(menu,"AI 帮我认认（消耗额度）",delegate{return controller.GuessDeviceTypesAsync();});menu.Items.Add(new ToolStripSeparator());menu.Items.Add("给表格中选中的设备起名字",null,delegate{EditDeviceLabel();});menu.Items.Add("查看选中设备的完整信息",null,delegate{ShowSelectedDeviceDetails();});menu.Items.Add("展开 / 收起技术记录",null,delegate{SetDetailedMode(!detailedMode,true);});menu.Items.Add("查看本次查找完整记录",null,delegate{ShowTextDetails("本次设备查找记录",controller.DeviceDiscoveryStatus??"还没有主动查找设备。");});more.Click+=delegate{menu.BackColor=Theme.Card;menu.ForeColor=Theme.Text;menu.Show(more,new Point(0,more.Height));};bar.Controls.Add(more);Add(p,bar,50);discoveryStatus=LabelText("平时只读记录；点“找一找设备”才会发送少量检查。",10,Theme.Muted,false);Add(p,discoveryStatus,36);Note(p,"这台电脑只记得一部分附近设备，通常不知道它们叫什么，也不知道各自用了多少网。你可以手动起名字；要查看用量，需要路由器提供记录。",65);deviceGrid=Grid(false);Col(deviceGrid,"name","这是什么设备",220);Col(deviceGrid,"hint","类型 / 我的备注",170);Col(deviceGrid,"nameSource","名字确认了吗",180);Col(deviceGrid,"down","下载用了多少网",160);Col(deviceGrid,"up","上传用了多少网",160);Col(deviceGrid,"reason","为什么还不知道",250);Col(deviceGrid,"ip","IP",140);Col(deviceGrid,"mac","MAC",170);Col(deviceGrid,"state","原始状态",150);Col(deviceGrid,"time","记录时刻",160);Col(deviceGrid,"source","数据来源",210);Col(deviceGrid,"reported","设备原始名称",180);deviceGrid.CellDoubleClick+=delegate(object sender,DataGridViewCellEventArgs e){if(e.RowIndex>=0)ShowSelectedDeviceDetails();};Note(p,"本机与当前 Wi-Fi / 网线下系统见过的设备",33);deviceCards=new CardFlowPanel();deviceCards.SizeChanged+=delegate{LayoutFriendlyCards(deviceCards);};Add(p,deviceCards,480);pendingAddressesLink=new LinkLabel{Text="查看待确认地址",Font=Theme.Font(10,FontStyle.Regular),LinkColor=Theme.Muted,ActiveLinkColor=Theme.Accent,TextAlign=ContentAlignment.MiddleLeft};pendingAddressesLink.LinkClicked+=delegate{var pending=controller.Devices.Where(IsPendingDeviceAddress).ToList();ShowTextDetails("待确认地址 · 还不能当作发现了设备",pending.Count==0?"当前没有待确认地址。":String.Join("\r\n\r\n",pending.Select(x=>x.Ip+"  ·  "+x.State+"\r\n"+deviceTopology.Locate(x).Description).ToArray())+"\r\n\r\n这些地址没有可确认的设备身份。失败的连接尝试也可能留下记录，因此不计入设备工位；原始表仍完整保留。");};Add(p,pendingAddressesLink,34);virtualDeviceHeading=LabelText("VPN / 虚拟连接记录（不是附近设备）",11,Theme.Muted,true);Add(p,virtualDeviceHeading,33);virtualDeviceCards=new CardFlowPanel();virtualDeviceCards.SizeChanged+=delegate{LayoutFriendlyCards(virtualDeviceCards);};Add(p,virtualDeviceCards,250);unknownDeviceHeading=LabelText("网络来源待确认",11,Theme.Muted,true);Add(p,unknownDeviceHeading,33);unknownDeviceCards=new CardFlowPanel();unknownDeviceCards.SizeChanged+=delegate{LayoutFriendlyCards(unknownDeviceCards);};Add(p,unknownDeviceCards,250);AddTechnical(p,TitledBox("设备原始记录 · 双击查看详情",deviceGrid),350);deviceSummary.ForeColor=Theme.Muted;deviceSummary.Text="用量显示“还不知道”并不代表没有用网。电脑看到设备地址，不等于能看到那台设备的流量。";Add(p,deviceSummary,70);ScopeLink(p,"路由器记录怎么导入？","需要从你的路由器或网关管理页面导出设备用网记录，再整理为 CSV。\n\nip 必填；可选 mac,name,device_type,download_bps,upload_bps,observed_at。\n\n用量单位是每秒字节（Bytes/s）；时间使用含时区的 ISO 8601。未提供的用量或时间会保留为未知。\n\n导入后显示的是那一刻的快照，不会持续刷新。\n\n程序目录提供了模板和说明。这里不会自动登录路由器，也不会扫描整个局域网。");connectionGrid=Grid(false);Col(connectionGrid,"process","进程",180);Col(connectionGrid,"pid","PID",85);Col(connectionGrid,"local","本地端点",230);Col(connectionGrid,"remote","远端端点",250);Col(connectionGrid,"state","TCP 状态",130);AddTechnical(p,TitledBox("本机连接技术记录 · 数量不能当作用量",connectionGrid),310);BuildProcessTraffic(p);}
