  void RefreshDiscoveryUi(){if(discoveryButton==null)return;discoveryButton.Text=controller.IsDeviceDiscovering?"停止查找":"找一找设备";if(discoveryStatus!=null&&!String.IsNullOrWhiteSpace(controller.DeviceDiscoveryStatus))discoveryStatus.Text=controller.DeviceDiscoveryStatus.Split(new[]{(char)13,(char)10},StringSplitOptions.RemoveEmptyEntries).FirstOrDefault();}
  void LayoutFriendlyCards(CardFlowPanel flow){if(flow==null||flow.ClientSize.Width<10)return;if((flow==virtualDeviceCards||flow==unknownDeviceCards)&&flow.Controls.Count==0)return;int columns=flow.ClientSize.Width>=1000?3:flow.ClientSize.Width>=640?2:1;int width=Math.Max(240,(flow.ClientSize.Width-(columns-1)*12)/columns);flow.SuspendLayout();for(int i=0;i<flow.Controls.Count;i++){flow.Controls[i].Width=width;flow.Controls[i].Margin=new Padding(0,0,(i%columns)==columns-1?0:12,12);}int rows=Math.Max(1,(flow.Controls.Count+columns-1)/columns);var stack=flow.Parent as TableLayoutPanel;if(stack!=null){int row=stack.GetRow(flow);if(row<0||row>=stack.RowStyles.Count){flow.ResumeLayout();return;}float height=rows*252+16;if(stack.RowStyles[row].Height!=height)stack.RowStyles[row].Height=height;}flow.ResumeLayout();}
  string PlainAdapterName(string value){string name=value??"选定连接";int cut=name.IndexOf("（",StringComparison.Ordinal);if(cut<0)cut=name.IndexOf("(",StringComparison.Ordinal);if(cut>=0)name=name.Substring(0,cut).Trim();return name.Equals("WLAN",StringComparison.OrdinalIgnoreCase)?"Wi-Fi":name;}
  string DeviceMacKey(DeviceInfo device){return System.Text.RegularExpressions.Regex.Replace(device.Mac??"","[^0-9A-Fa-f]","").ToUpperInvariant();}
  bool IsLocalDevice(DeviceInfo device){return(device.Source??"").StartsWith("本机接口",StringComparison.Ordinal);}
  bool IsGroupRecord(DeviceInfo device){string mac=DeviceMacKey(device);if(mac=="FFFFFFFFFFFF")return true;int first;if(mac.Length==12&&Int32.TryParse(mac.Substring(0,2),System.Globalization.NumberStyles.HexNumber,System.Globalization.CultureInfo.InvariantCulture,out first)&&(first&1)==1)return true;System.Net.IPAddress address;if(System.Net.IPAddress.TryParse(device.Ip,out address)){byte[] bytes=address.GetAddressBytes();if(bytes.Length==16&&bytes[0]==255)return true;if(bytes.Length==4&&bytes[0]>=224&&bytes[0]<=239)return true;if(bytes.Length==4&&bytes.All(x=>x==255))return true;}return false;}
  async Task LoadDeviceRecordsAsync(bool force){if(renderingPreview||IsDisposed||deviceReadInProgress)return;if(!force&&(DateTime.UtcNow-lastDeviceReadRequested).TotalSeconds<10)return;deviceReadInProgress=true;lastDeviceReadRequested=DateTime.UtcNow;deviceSummary.Text="正在读取 Windows 已经记住的设备记录；不会扫描网络。";try{await controller.RefreshDevicesAsync();if(!IsDisposed)RefreshDevices();}catch(Exception ex){if(!IsDisposed)deviceSummary.Text="这次没有读到设备记录："+ex.Message+"。可以点上方按钮重试。";}finally{deviceReadInProgress=false;}}
  void EnsureDeviceTopology(List<DeviceInfo> devices){var current=controller.CurrentLocal;string key=(current==null?"no-local":String.Join("|",current.Adapters.Select(x=>x.Id+"/"+x.Name+"/"+x.IsUp+"/"+x.IsVirtual+"/"+x.Gateways).ToArray()))+"/"+String.Join("|",devices.Select(x=>x.Source+"/"+x.ObservedAt).ToArray());if(deviceTopology==null||key!=deviceTopologyKey){deviceTopology=DeviceTopology.Read(current);deviceTopologyKey=key;}}
  void ShowDeviceSection(Control heading,CardFlowPanel flow,bool visible){if(heading!=null){heading.Visible=visible;var headingStack=heading.Parent as TableLayoutPanel;if(headingStack!=null){int row=headingStack.GetRow(heading);if(row>=0&&row<headingStack.RowStyles.Count)headingStack.RowStyles[row].Height=visible?49:0;}}flow.Visible=visible;var stack=flow.Parent as TableLayoutPanel;if(!visible&&stack!=null){int row=stack.GetRow(flow);if(row>=0&&row<stack.RowStyles.Count)stack.RowStyles[row].Height=0;}else if(visible)LayoutFriendlyCards(flow);}
  void RefreshFriendlyCards(){if(deviceCards==null||virtualDeviceCards==null||unknownDeviceCards==null||processCards==null)return;var list=controller.Devices;var local=controller.CurrentLocal;EnsureDeviceTopology(list);string key=String.Join("|",list.Select(x=>x.Ip+"/"+x.Mac+"/"+x.Name+"/"+x.Hint+"/"+x.NameSource+"/"+x.DownloadBps+"/"+x.UploadBps+"/"+x.ObservedAt+"/"+x.InferredType+"/"+x.InferenceReason+"/"+x.InferenceConfidence).ToArray())+"/local="+(local!=null)+"/topology="+deviceTopologyKey;if(key!=lastDeviceCardsKey||deviceCards.Controls.Count==0){lastDeviceCardsKey=key;foreach(var flow in new[]{deviceCards,virtualDeviceCards,unknownDeviceCards}){flow.SuspendLayout();foreach(Control old in flow.Controls.Cast<Control>().ToList())old.Dispose();flow.Controls.Clear();}localDeviceTile=null;if(local!=null||list.Any(IsLocalDevice)){localDeviceTile=new FriendlyTile();localDeviceTile.NameLabel.Text="这台电脑";localDeviceTile.StateLabel.Text="已确认是本机 · 多个网络连接合并显示";localDeviceTile.Glyph.Kind="电脑";localDeviceTile.ActionButton.Text="看看这台电脑的网络";localDeviceTile.ActionButton.Click+=delegate{SelectPage(3);};deviceCards.Controls.Add(localDeviceTile);}int pendingCount=list.Count(IsPendingDeviceAddress);pendingAddressesLink.Text=pendingCount==0?"没有待确认地址":pendingCount+" 条待确认地址（还不能算发现了设备） · 点此查看";var groups=list.Where(x=>!IsLocalDevice(x)&&!IsGroupRecord(x)&&!IsPendingDeviceAddress(x)).GroupBy(x=>deviceTopology.Locate(x).Scope+"|"+deviceTopology.Locate(x).InterfaceIndex+"|"+x.Ip).Select(g=>g.OrderByDescending(CanNameDevice).ThenByDescending(x=>(x.State??"").Contains("本次ICMP回应")).ThenByDescending(x=>(x.NameSource??"").Contains("人工")).ThenByDescending(x=>x.ObservedAt??DateTime.MinValue).First()).GroupBy(x=>deviceTopology.Locate(x).Scope+"|"+(CanNameDevice(x)?"mac:"+DeviceMacKey(x):"ip:"+x.Ip)).Take(64).ToList();int physicalCount=0,virtualCount=0,unknownCount=0;foreach(var group in groups){var d=group.OrderByDescending(x=>(x.NameSource??"").Contains("人工")).ThenByDescending(x=>x.ObservedAt??DateTime.MinValue).First();var location=deviceTopology.Locate(d);var destination=location.Scope=="physical"?deviceCards:location.Scope=="virtual"?virtualDeviceCards:unknownDeviceCards;if(location.Scope=="physical")physicalCount++;else if(location.Scope=="virtual")virtualCount++;else unknownCount++;int addressCount=group.Select(x=>x.Ip).Distinct().Count();var tile=new FriendlyTile();tile.NameLabel.Text=!CanNameDevice(d)&&(d.State??"").Contains("本次ICMP回应")?"有回应的设备（未命名）":DeviceFriendlyName(d);tile.StateLabel.Text=location.Scope=="virtual"?"属于 "+location.AdapterName+" · 不是附近设备":location.IsGateway&&location.Scope=="physical"?"系统把它用作这条网络的入口":(d.State??"").Contains("本次ICMP回应")?"在 "+(d.ObservedAt.HasValue?Theme.LocalTime(d.ObservedAt.Value):"记录时刻")+" 有回应 · 名称未确认":DeviceTypeDescription(d)+" · "+DeviceNameConfidence(d);tile.Glyph.Kind=location.Scope=="virtual"?"虚拟连接":location.IsGateway&&location.Scope=="physical"?"路由器":DeviceTypeIcon(d);tile.UsageLabel.Text=d.DownloadBps.HasValue||d.UploadBps.HasValue?"↓ "+(d.DownloadBps.HasValue?Theme.Rate(d.DownloadBps.Value):"未知")+"  ↑ "+(d.UploadBps.HasValue?Theme.Rate(d.UploadBps.Value):"未知"):"用网多少：现在还不知道";tile.ReasonLabel.Text=location.Scope=="virtual"?"这条记录来自 VPN / 虚拟连接，不能当作同一 Wi-Fi 下的设备。":(addressCount>1?"合并 "+addressCount+" 条地址。":"")+"系统缓存记录，不确认现在在线。"+DeviceUnknownReason(d);bool canName=CanNameDevice(d);tile.ActionButton.Text=!canName?"查看这条记录":(d.NameSource??"").Contains("人工")?"修改名字 / 我的备注":"给它起个名字";tile.ActionButton.Click+=delegate{if(!canName){ShowDeviceDetails(d);return;}foreach(DataGridViewRow row in deviceGrid.Rows){var item=row.Tag as DeviceInfo;if(item!=null&&item.Ip==d.Ip&&item.Mac==d.Mac){deviceGrid.CurrentCell=row.Cells["name"];row.Selected=true;EditDeviceLabel();break;}}};tile.Click+=delegate{ShowDeviceDetails(d);};foreach(Control part in new Control[]{tile.NameLabel,tile.StateLabel,tile.UsageLabel,tile.ReasonLabel,tile.Glyph}){part.Cursor=Cursors.Hand;part.Click+=delegate{ShowDeviceDetails(d);};}destination.Controls.Add(tile);}if(physicalCount==0){var empty=new FriendlyTile();empty.NameLabel.Text="还没有其他 Wi-Fi / 网线设备记录";empty.StateLabel.Text="不代表附近没有其他设备";empty.UsageLabel.Text="只能看到系统已经记住的部分";empty.ReasonLabel.Text="本程序不扫描整个网络。VPN 记录和无法确认来源的记录会放在下面，原始记录仍全部保留。";empty.ActionButton.Text="为什么看不全？";empty.ActionButton.Click+=delegate{ShowTextDetails("为什么看不全设备？","Windows 只保留一部分最近见过的设备地址。这不是整个局域网的设备清单。\r\n\r\nWi-Fi/网线、VPN/虚拟连接与来源待确认的记录分开展示；未确认单播候选仍保留，广播和组播只在详细表中。\r\n\r\n完整设备清单和每台设备的用量需要路由器提供。您可导入记录，并手动给设备起名。");};deviceCards.Controls.Add(empty);}deviceSummary.Text="读到 "+physicalCount+" 组 Wi-Fi / 网线设备记录、"+virtualCount+" 组 VPN / 虚拟记录、"+unknownCount+" 组来源待确认记录。缓存状态不等于当前在线；用量需要路由器提供。";LayoutFriendlyCards(deviceCards);ShowDeviceSection(virtualDeviceHeading,virtualDeviceCards,virtualCount>0);ShowDeviceSection(unknownDeviceHeading,unknownDeviceCards,unknownCount>0);foreach(var flow in new[]{deviceCards,virtualDeviceCards,unknownDeviceCards})flow.ResumeLayout();}if(localDeviceTile!=null){localDeviceTile.UsageLabel.Text=local!=null&&local.TrafficRateReady?"↓ "+Theme.Rate(local.DownloadBps)+"  ↑ "+Theme.Rate(local.UploadBps):"本机用量：等待下一次采样";localDeviceTile.ReasonLabel.Text=local==null?"本机身份已确认，正在等网络用量记录。":"这里统计 "+PlainAdapterName(local.TrafficAdapterName)+" 当前用了多少网，不代表宽带最高速度。";}processCards.SuspendLayout();foreach(Control old in processCards.Controls.Cast<Control>().ToList())old.Dispose();processCards.Controls.Clear();var snap=controller.ProcessTraffic;if(IsCurrentProcessSnapshot(snap)&&snap.Processes!=null&&snap.Processes.Count>0){foreach(var value in snap.Processes.OrderByDescending(x=>x.DownloadBps+x.UploadBps).Take(12)){var row=value;var tile=new FriendlyTile();tile.Glyph.Kind="程序";tile.NameLabel.Text=FriendlyNames.ProcessLabel(row.Name,row.Pid);tile.StateLabel.Text="本次观测 · "+Theme.LocalTime(snap.At);tile.UsageLabel.Text="↓ "+Theme.Rate(row.DownloadBps)+"   ↑ "+Theme.Rate(row.UploadBps);tile.ReasonLabel.Text=snap.LostEvents>0?"有记录丢失，本次统计不完整。":"同一份数据可能也被中转工具统计，不能单凭数字认定抢网。";tile.ActionButton.Text="看看这个程序的变化";tile.ActionButton.Click+=delegate{foreach(DataGridViewRow item in processGrid.Rows){var selection=item.Tag as ProcessSelection;if(selection!=null&&selection.Pid==row.Pid&&selection.Name==row.Name){processGrid.CurrentCell=item.Cells["process"];item.Selected=true;ShowProcessHistory();break;}}};processCards.Controls.Add(tile);}}else{var empty=new FriendlyTile();empty.Glyph.Kind="程序";empty.NameLabel.Text="程序用量还查不到";empty.StateLabel.Text=snap==null?"开始前需要你同意管理员权限":"目前没有新的有效用量记录";empty.UsageLabel.Text="连接多，不代表用网多";empty.ReasonLabel.Text="点上方“开始看程序用网”后，才会有实际用量记录。";empty.ActionButton.Text="为什么需要权限？";empty.ActionButton.Click+=delegate{ShowTextDetails("为什么需要管理员权限？","Windows 的逐程序用网统计需要额外权限。\r\n\r\n只有你点击上方按钮并同意系统提示后才会开启。程序只统计数据字节数量，不读取聊天、网页或文件内容。\r\n\r\n不同应用和中转工具可能重复记录同一份数据，因此数字不是宽带占用的精确分配。");};processCards.Controls.Add(empty);}LayoutFriendlyCards(processCards);processCards.ResumeLayout();}
  void ShowDeviceDetails(DeviceInfo device){if(device==null)return;ShowTextDetails("设备详情 · "+DeviceFriendlyName(device),"显示名称："+DeviceFriendlyName(device)+"\r\n名字来源："+DeviceNameConfidence(device)+"\r\n类型判断："+DeviceTypeDescription(device)+"\r\nAI 推测原因："+(String.IsNullOrWhiteSpace(device.InferenceReason)?"尚无 AI 推测记录":device.InferenceReason)+"\r\n类型 / 我的备注："+device.Hint+"\r\n\r\n为什么还不知道："+DeviceUnknownReason(device)+"\r\n\r\n原始名称："+device.ReportedName+"\r\n原始类型提示："+device.ReportedHint+"\r\n名称来源原文："+device.NameSource+"\r\nIP："+device.Ip+"\r\nMAC："+device.Mac+"\r\n原始状态："+device.State+"\r\n所属连接："+(deviceTopology==null?"尚未确认":deviceTopology.Locate(device).Description)+"\r\n数据来源："+device.Source+"\r\n记录时刻："+(device.ObservedAt.HasValue?Theme.LocalTime(device.ObservedAt.Value):"未提供，不能当成实时数据")+"\r\n下载记录："+(device.DownloadBps.HasValue?Theme.Rate(device.DownloadBps.Value):"没有记录")+"\r\n上传记录："+(device.UploadBps.HasValue?Theme.Rate(device.UploadBps.Value):"没有记录")+"\r\n\r\n同名不表示同一个人。手动名称只绑定这个 MAC 地址。");}
  string InferredDeviceType(DeviceInfo device){switch(device.InferredType??""){case"windows_computer":return"Windows 电脑";case"mac_computer":return"Mac 电脑";case"iphone":return"iPhone 手机";case"ipad":return"iPad 平板";case"android_device":return"Android 设备";case"router":return"路由器";case"printer":return"打印机";case"nas":return"存储设备";case"tv":return"电视";case"game_console":return"游戏机";default:return"";}}
  string DeviceTypeDescription(DeviceInfo device){if(IsLocalDevice(device))return"已确认是这台电脑";if((device.NameSource??"").Contains("人工"))return FriendlyNames.DeviceGuess(device);string inferred=InferredDeviceType(device);if(!String.IsNullOrEmpty(inferred))return"AI 推测："+inferred+"（"+(device.InferenceConfidence=="medium"?"把握一般":"把握较低")+"）";return FriendlyNames.DeviceGuess(device);}
  string DeviceTypeIcon(DeviceInfo device){if(IsLocalDevice(device))return"电脑";if(!(device.NameSource??"").Contains("人工")){string inferred=InferredDeviceType(device);if(!String.IsNullOrEmpty(inferred)){if(inferred.Contains("Android"))return"手机";return inferred;}}return FriendlyNames.DeviceType(device);}
  bool IsPendingDeviceAddress(DeviceInfo device){return !IsLocalDevice(device)&&!IsGroupRecord(device)&&!CanNameDevice(device)&&!(device.State??"").Contains("本次ICMP回应")&&deviceTopology!=null&&!deviceTopology.Locate(device).IsGateway&&deviceTopology.Locate(device).Scope!="virtual";}
  bool CanNameDevice(DeviceInfo device){string mac=System.Text.RegularExpressions.Regex.Replace(device.Mac??"","[^0-9A-Fa-f]","");return mac.Length==12&&mac!="000000000000"&&!mac.Equals("FFFFFFFFFFFF",StringComparison.OrdinalIgnoreCase);}
  string DeviceFriendlyName(DeviceInfo device){string name=device.Name??"";if(!String.IsNullOrWhiteSpace(name)&&name!="未知"&&name!="未识别")return name;var location=deviceTopology==null?null:deviceTopology.Locate(device);if(location!=null&&location.Scope=="physical"&&location.IsGateway)return"路由器 / 网络入口";if(location!=null&&location.Scope=="virtual")return location.IsGateway?"VPN / 虚拟连接的入口记录":"VPN / 虚拟连接记录";string mac=(device.Mac??"").Replace("-","").Replace(":","");if(mac.Equals("FFFFFFFFFFFF",StringComparison.OrdinalIgnoreCase))return"广播记录（不是单台设备）";if((device.Source??"").StartsWith("本机接口",StringComparison.Ordinal))return"这台电脑的一个网络接口";return"还不知道叫什么";}
  string DeviceNameConfidence(DeviceInfo device){if((device.NameSource??"").Contains("人工"))return"你已手动确认";if((device.NameSource??"").Contains("网关"))return"路由器提供，尚未人工确认";if((device.Source??"").StartsWith("本机接口",StringComparison.Ordinal))return"本机系统提供";return"还没有确认名字";}
  string DeviceUnknownReason(DeviceInfo device){if(device.DownloadBps.HasValue||device.UploadBps.HasValue)return"仅导入时刻的记录，不代表现在";if(DeviceFriendlyName(device)=="还不知道叫什么")return"电脑只记住了地址；名字和用量都需要补充";return"没有路由器提供的用网记录";}
  void ShowSelectedDeviceDetails(){if(deviceGrid.CurrentRow==null){MessageBox.Show(this,"先点击一台设备，或点击它的卡片文字。","设备详情");return;}ShowDeviceDetails(deviceGrid.CurrentRow.Tag as DeviceInfo);}
  void BuildProcessTraffic(Panel page){Note(page,"想知道这台电脑上哪个程序用了多少网，需要你同意管理员权限。这里只数用量，不读取聊天或网页内容。应用和中转工具可能重复计数，不能据此断定谁在抢网。",65);var bar=Bar();var start=ButtonText("开始看程序用网",true);start.Width=215;start.Click+=delegate{try{controller.StartProcessTraffic();RefreshProcessTraffic();}catch(Exception ex){ShowError(ex);}};bar.Controls.Add(start);var stop=ButtonText("停止统计",false);stop.Width=145;stop.Click+=delegate{try{controller.StopProcessTraffic();RefreshProcessTraffic();}catch(Exception ex){ShowError(ex);}};bar.Controls.Add(stop);var history=ButtonText("查看程序走势",false);history.Width=160;history.Click+=delegate{ShowProcessHistory();};bar.Controls.Add(history);var export=ButtonText("保存程序记录",false);export.Width=145;export.Click+=delegate{SaveDialog("CSV 数据|*.csv","NetScope-process-24h.csv",delegate(string path){controller.ExportProcessHistoryCsv(path,TimeSpan.FromHours(24));});};bar.Controls.Add(export);Add(page,bar,104);processStatusLabel.ForeColor=Theme.Muted;processStatusLabel.Text="还没开启程序用网统计。你仍然可以检查网络；同意管理员权限后，才能补上程序用量。";Add(page,processStatusLabel,52);processGrid=Grid(false);Col(processGrid,"process","程序名称",230);Col(processGrid,"pid","PID",80);Col(processGrid,"download","当前下载用量",140);Col(processGrid,"upload","当前上传用量",140);Col(processGrid,"rxBytes","接收事件字节",110);Col(processGrid,"txBytes","发送事件字节",110);Col(processGrid,"share","观测事件占比",140);Col(processGrid,"evidence","这份记录什么时候采集",230);processCards=new CardFlowPanel();processCards.SizeChanged+=delegate{LayoutFriendlyCards(processCards);};Add(page,processCards,250);AddTechnical(page,TitledBox("程序用网原始记录",processGrid),350);}
  string ProcessStateText(string state){switch(state){case "Starting":return "正在启动";case "Running":return "深度监测中";case "PermissionRequired":return "需要管理员权限";case "Error":return "采集未完成";case "Stopped":return "已停止";default:return "未启用";}}
  bool IsCurrentProcessSnapshot(ProcessTrafficSnapshot snapshot){return snapshot!=null&&snapshot.State=="Running"&&snapshot.IntervalSeconds>0&&(DateTime.UtcNow-snapshot.At.ToUniversalTime()).TotalSeconds<12&&!(controller.ProcessTrafficStatus??"").Contains("已停止");}
  void RefreshProcessTraffic(){if(processGrid==null)return;var selectedProcess=processGrid.CurrentRow!=null&&processGrid.CurrentRow.Selected?processGrid.CurrentRow.Tag as ProcessSelection:null;var snapshot=controller.ProcessTraffic;processGrid.Rows.Clear();if(snapshot==null){processStatusLabel.Text=detailedMode?(controller.ProcessTrafficStatus??"未开启"):"还没有开始统计程序用量。点上方按钮并同意系统权限提示后，再看看。";processGrid.Rows.Add("等待深度模式数据","—","不可得","不可得","不可得","不可得","不可得","未启用或尚无事件");return;}bool live=IsCurrentProcessSnapshot(snapshot);processStatusLabel.Text=ProcessStateText(snapshot.State)+" · "+(snapshot.At==DateTime.MinValue?"尚无采集时间":Theme.LocalTime(snapshot.At))+" · 采样间隔 "+snapshot.IntervalSeconds.ToString("0.0")+" 秒"+(snapshot.LostEvents>0?" · 丢失 "+snapshot.LostEvents+" 个事件，统计不完整":"")+(String.IsNullOrWhiteSpace(snapshot.Error)?"":"\n"+snapshot.Error);processStatusLabel.ForeColor=snapshot.LostEvents>0||snapshot.State=="Error"?Theme.Amber:Theme.Muted;if(snapshot.Processes!=null)foreach(var row in snapshot.Processes.OrderByDescending(x=>x.ObservedSharePercent)){bool ready=snapshot.IntervalSeconds>0;int i=processGrid.Rows.Add(row.Name,row.Pid,ready?Theme.Rate(row.DownloadBps):"等待",ready?Theme.Rate(row.UploadBps):"等待",row.ReceivedBytes.ToString("N0")+" B",row.SentBytes.ToString("N0")+" B",ready?Percent(row.ObservedSharePercent):"等待",(live?"本次采样":"历史快照")+" · "+(row.Note??""));processGrid.Rows[i].Tag=new ProcessSelection{InstanceId=row.InstanceId,Pid=row.Pid,Name=row.Name};foreach(DataGridViewCell cell in processGrid.Rows[i].Cells)cell.ToolTipText=Convert.ToString(cell.Value);}if(processGrid.Rows.Count==0)processGrid.Rows.Add("本轮暂无进程事件","—","—","—","—","—","—",live?"等待下一轮事件":"当前没有可用事件数据");processGrid.ClearSelection();if(selectedProcess!=null)foreach(DataGridViewRow gridRow in processGrid.Rows){var item=gridRow.Tag as ProcessSelection;if(item!=null&&item.Key==selectedProcess.Key){processGrid.CurrentCell=gridRow.Cells[0];gridRow.Selected=true;break;}}}
  class ProcessSelection {public string InstanceId;public int Pid;public string Name;public string Key{get{return String.IsNullOrWhiteSpace(InstanceId)?"pid:"+Pid+"|"+Name:"instance:"+InstanceId;}}}
  void ShowProcessHistory(){var selected=processGrid.CurrentRow!=null&&processGrid.CurrentRow.Selected?processGrid.CurrentRow.Tag as ProcessSelection:null;if(selected==null){MessageBox.Show(this,"先在进程流量表中选择一个进程。","进程走势");return;}try{var data=controller.GetProcessHistory(TimeSpan.FromMinutes(10));var down=new ChartSeries("接收事件速率",Theme.Accent);var up=new ChartSeries("发送事件速率",Theme.Blue);foreach(var sample in data.OrderBy(x=>x.At)){var row=sample.Processes==null?null:sample.Processes.FirstOrDefault(x=>!String.IsNullOrWhiteSpace(selected.InstanceId)?x.InstanceId==selected.InstanceId:x.Pid==selected.Pid&&x.Name==selected.Name);bool valid=row!=null&&sample.State=="Running"&&sample.IntervalSeconds>0;down.Points.Add(new ChartPoint(sample.At,valid?(double?)row.DownloadBps:null,selected.Key));up.Points.Add(new ChartPoint(sample.At,valid?(double?)row.UploadBps:null,selected.Key));}down.Points=BreakGaps(down.Points,TimeSpan.FromSeconds(8));up.Points=BreakGaps(up.Points,TimeSpan.FromSeconds(8));using(var dialog=new Form{Text="进程近期走势 · "+selected.Name,ClientSize=new Size(980,530),MinimumSize=new Size(760,440),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Back,ForeColor=Theme.Text,Font=Font}){var chart=new TimeChart{Dock=DockStyle.Fill,GapLimit=TimeSpan.FromSeconds(8),EmptyText="当前运行的最近 10 分钟暂无此进程样本；仅记录启用深度监测后的事件。"};DateTime end=DateTime.UtcNow;chart.UpdateData(new List<ChartSeries>{down,up},end.AddMinutes(-10),end,true);var description=LabelText(selected.Name+" · PID "+selected.Pid+"\n仅当前运行最近 10 分钟，缺测断线。曲线是观测到的 ETW 事件速率，不是物理带宽。\n"+(String.IsNullOrWhiteSpace(selected.InstanceId)?"未提供进程实例标识，按 PID + 名称匹配。":"按进程实例标识匹配，避免 PID 重用混淆。")+" 长期记录可返回设备页导出 24 小时 CSV。",9,Theme.Muted,false);description.Height=84;description.Dock=DockStyle.Top;description.Padding=new Padding(18,8,18,8);var box=new SurfacePanel{Dock=DockStyle.Fill,Padding=new Padding(12)};box.Controls.Add(chart);dialog.Controls.Add(box);dialog.Controls.Add(description);dialog.ShowDialog(this);}}catch(Exception ex){ShowError(ex);}}
