  string ConfidenceText(string value){switch((value??"").ToLowerInvariant()){case "high":return "高";case "medium":return "中";case "low":return "低";default:return "未提供";}}
  string AssessmentText(string value){switch((value??"").ToLowerInvariant()){case "supported":return "有证据支持";case "possible":return "仍有可能";case "not_supported":return "目前看不像";default:return "还不够确定";}}
  void RefreshAiResult(){if(aiSummaryLabel==null||aiAlternativesGrid==null||aiEvidenceGrid==null)return;var report=controller.CurrentAiReport;if(report==null){aiSummaryLabel.Text="等待首次分析";aiCauseLabel.Text="完成一次分析后，在这里查看有证据支持的可能原因。";aiConfidenceCard.ValueText="待分析";aiConfidenceCard.Detail="暂无结构化结论";aiConfidenceCard.AccentColor=Theme.Muted;if(aiBox!=null)aiBox.Text=controller.LastAiAt.HasValue&&!String.IsNullOrWhiteSpace(controller.LastAiAnalysis)?controller.LastAiAnalysis:"等待首次分析。";return;}string key=(controller.LastAiAt.HasValue?controller.LastAiAt.Value.ToString("o"):"")+report.Summary+report.Details+report.PrimaryCause;if(key==aiStructuredKey)return;aiStructuredKey=key;aiSummaryLabel.Text=String.IsNullOrWhiteSpace(report.Summary)?"本轮未返回概览，请查看完整依据。":report.Summary;aiSummaryLabel.ForeColor=report.Status=="normal"?Theme.Accent:report.Status=="attention"?Theme.Amber:Theme.Text;aiSummaryLabel.AutoEllipsis=true;aiCauseLabel.Text=String.IsNullOrWhiteSpace(report.PrimaryCause)?"当前证据不足以给出主要原因。":report.PrimaryCause;aiCauseLabel.AutoEllipsis=true;aiConfidenceCard.ValueText=ConfidenceText(report.Confidence);aiConfidenceCard.Detail=report.Status=="normal"?"本轮无明显异常证据":report.Status=="attention"?"建议进一步检查":"还需要更多记录";aiConfidenceCard.AccentColor=report.Confidence=="high"?Theme.Accent:report.Confidence=="medium"?Theme.Amber:Theme.Muted;aiConfidenceCard.Invalidate();aiAlternativesGrid.Rows.Clear();int rank=1;if(report.Alternatives!=null)foreach(var item in report.Alternatives.Where(x=>x!=null)){int row=aiAlternativesGrid.Rows.Add((rank++)+". "+item.Cause,AssessmentText(item.Assessment)+" · "+ConfidenceText(item.Confidence),item.Reason);aiAlternativesGrid.Rows[row].Cells["support"].Style.ForeColor=item.Assessment=="supported"?Theme.Accent:item.Assessment=="possible"?Theme.Amber:Theme.Muted;foreach(DataGridViewCell cell in aiAlternativesGrid.Rows[row].Cells)cell.ToolTipText=Convert.ToString(cell.Value);}if(aiAlternativesGrid.Rows.Count==0)aiAlternativesGrid.Rows.Add("未提供其他原因","还不够确定","可查看完整依据");aiAlternativesGrid.ClearSelection();aiEvidenceGrid.Rows.Clear();if(report.Evidence!=null)foreach(var item in report.Evidence.Where(x=>x!=null)){int row=aiEvidenceGrid.Rows.Add(item.Metric,item.Value,item.Meaning);aiEvidenceGrid.Rows[row].Tag=item;foreach(DataGridViewCell cell in aiEvidenceGrid.Rows[row].Cells)cell.ToolTipText=Convert.ToString(cell.Value)+"\n来源：本机匿名测量摘要，由AI整理。\n"+AiInputScope()+"\n双击查看完整来源。";}if(aiEvidenceGrid.Rows.Count==0)aiEvidenceGrid.Rows.Add("未提供关键测量","—","请结合完整依据判断");aiEvidenceGrid.ClearSelection();aiNextStepsLabel.Text=report.NextSteps==null||report.NextSteps.Count==0?"未提供后续建议。":String.Join("\n",report.NextSteps.Where(x=>!String.IsNullOrWhiteSpace(x)).Take(3).Select((s,i)=>(i+1)+". "+s).ToArray());if(aiInputBox!=null)aiInputBox.Text=String.IsNullOrWhiteSpace(controller.LastAiInput)?"尚无对应的分析输入记录。":controller.LastAiInput;if(aiBox!=null)aiBox.Text=(controller.LastAiAt.HasValue?"分析时间："+Theme.LocalTime(controller.LastAiAt.Value)+"\r\n\r\n":"")+(String.IsNullOrWhiteSpace(report.Details)?"本轮未提供补充详情。":report.Details);}
  string AiInputScope(){string input=controller.LastAiInput??"";var line=input.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).FirstOrDefault(x=>x.TrimStart().StartsWith("记录时段：",StringComparison.Ordinal));return line??"原始摘要未提供统一记录时段；未单列的采样时刻保持未知。";}
  void ShowEvidenceDetails(AiEvidence evidence){string overview="测量项："+evidence.Metric+"\r\n数值 / 结果："+evidence.Value+"\r\nAI 解释："+evidence.Meaning+"\r\n\r\n来源：此次分析实际收到的本机匿名测量摘要，由 AI 整理。\r\n"+AiInputScope()+"\r\n分析生成时间："+(controller.LastAiAt.HasValue?controller.LastAiAt.Value.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss"):"未提供")+"（不是测量时间）";using(var dialog=new Form{Text="为什么这样判断 · "+evidence.Metric,ClientSize=new Size(860,640),MinimumSize=new Size(680,440),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Back,ForeColor=Theme.Text,Font=Font}){var text=TextBoxDark(true);text.ReadOnly=true;text.Dock=DockStyle.Fill;text.Text=overview+"\r\n\r\n──── 此次分析实际输入 ────\r\n"+(controller.LastAiInput??"未记录");var body=new SurfacePanel{Dock=DockStyle.Fill};body.Controls.Add(text);dialog.Controls.Add(body);var actions=Bar();actions.Dock=DockStyle.Bottom;actions.Height=48;actions.Padding=new Padding(12,6,0,0);var copy=ButtonText("复制这条证据",false);copy.Width=150;copy.Click+=delegate{CopyText(overview);};actions.Controls.Add(copy);var close=ButtonText("关闭",true);close.DialogResult=DialogResult.OK;actions.Controls.Add(close);dialog.Controls.Add(actions);dialog.AcceptButton=close;dialog.ShowDialog(this);}}
  void BuildQuota(Panel page){var bar=Bar();quotaRefresh=ButtonText("刷新账户额度",true);quotaRefresh.Width=150;quotaRefresh.Click+=async delegate{quotaRefresh.Enabled=false;try{await controller.RefreshQuotaAsync();RefreshQuotaView();}catch(Exception ex){ShowError(ex);}finally{quotaRefresh.Enabled=true;}};bar.Controls.Add(quotaRefresh);var label=LabelSized("账户共享额度与下方本应用的调用 / token 统计分开计算。",420);bar.Controls.Add(label);Add(page,bar,44);var cards=new TableLayoutPanel{ColumnCount=2,RowCount=1,BackColor=Theme.Back};cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));quotaRemainingCard.Caption="账户共享剩余额度";quotaRemainingCard.ValueText="未查询";quotaRemainingCard.Detail="完整窗口明细见下方";quotaRemainingCard.AccentColor=Theme.Accent;quotaCreditCard.Caption="免费完整重置机会";quotaCreditCard.ValueText="未查询";quotaCreditCard.Detail="可用次数和过期时间取自账户接口";quotaCreditCard.AccentColor=Theme.Blue;quotaCreditCard.Margin=Padding.Empty;quotaRemainingCard.Dock=DockStyle.Fill;quotaCreditCard.Dock=DockStyle.Fill;cards.Controls.Add(quotaRemainingCard,0,0);cards.Controls.Add(quotaCreditCard,1,0);Add(page,cards,136);quotaGrid=Grid(false);Col(quotaGrid,"name","共享额度窗口",200);Col(quotaGrid,"used","已使用",100);Col(quotaGrid,"remaining","剩余",100);Col(quotaGrid,"reset","重置时间（本地）",205);Col(quotaGrid,"period","窗口长度",120);Add(page,TitledBox("账户额度窗口 / 自动后台刷新间隔 10 分钟",quotaGrid),172);quotaMetadata.ForeColor=Theme.Muted;quotaMetadata.Font=Theme.Font(9,FontStyle.Regular);quotaMetadata.Text="尚未查询账户额度。";Add(page,quotaMetadata,72);}
  string Percent(double n){return Double.IsNaN(n)||Double.IsInfinity(n)?"接口未提供":n.ToString("0.##")+"%";}
  void RefreshQuotaView(){if(quotaGrid==null)return;var q=controller.Quota;quotaGrid.Rows.Clear();if(q==null){quotaRemainingCard.ValueText="未查询";quotaRemainingCard.Detail="点击刷新账户额度";quotaMetadata.Text="账户额度接口尚未返回数据。";return;}var windows=q.Windows;var w=windows==null?null:windows.OrderBy(x=>x.RemainingPercent).FirstOrDefault();quotaRemainingCard.ValueText=w==null?"接口未提供":Percent(w.RemainingPercent);quotaRemainingCard.Detail=w==null?"尚无额度窗口明细":w.Name+" · 当前剩余比例最低的窗口";quotaRemainingCard.AccentColor=w!=null&&w.RemainingPercent<20?Theme.Amber:Theme.Accent;quotaCreditCard.ValueText=q.ResetCreditsAvailable.HasValue?q.ResetCreditsAvailable.Value+" 次":"接口未提供";quotaCreditCard.Detail=q.ResetCreditExpiresAt.HasValue?"过期："+q.ResetCreditExpiresAt.Value.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss"):"过期时间：接口未提供";if(windows!=null)foreach(var win in windows)quotaGrid.Rows.Add(win.Name,Percent(win.UsedPercent),Percent(win.RemainingPercent),win.ResetAt.HasValue?win.ResetAt.Value.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss"):"接口未提供",win.WindowMinutes.HasValue?win.WindowMinutes.Value+" 分钟":"接口未提供");if(quotaGrid.Rows.Count==0)quotaGrid.Rows.Add("接口未提供","—","—","—","—");quotaGrid.ClearSelection();quotaMetadata.Text="套餐："+(String.IsNullOrWhiteSpace(q.Plan)?"接口未提供":q.Plan)+"   Credit 余额："+(String.IsNullOrWhiteSpace(q.CreditBalance)?"接口未提供":q.CreditBalance)+"   可用 credits："+(q.HasCredits.HasValue?(q.HasCredits.Value?"是":"否"):"接口未提供")+"   无限 credits："+(q.UnlimitedCredits.HasValue?(q.UnlimitedCredits.Value?"是":"否"):"接口未提供")+"\n查询："+(q.At==DateTime.MinValue?"尚未查询":q.At.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss"))+"   "+(q.Status??"")+(String.IsNullOrWhiteSpace(q.Error)?"":" · "+q.Error);quotaRemainingCard.Invalidate();quotaCreditCard.Invalidate();}
  public void RenderSectionForTest(int index,int offset,string path){renderScrollOffset=offset;try{RenderPageForTest(index,path);}finally{renderScrollOffset=0;}}
