  public void RenderPageForTest(int index,string path){if(index<0||index>=pages.Count)throw new ArgumentOutOfRangeException("index");bool shown=Visible;var oldBounds=Bounds;var oldTaskbar=ShowInTaskbar;int oldPage=activePage;renderingPreview=true;try{if(!shown){StartPosition=FormStartPosition.Manual;Location=new Point(-20000,-20000);ShowInTaskbar=false;Show();}SelectPage(index);PerformLayout();Application.DoEvents();pages[index].AutoScrollPosition=new Point(0,renderScrollOffset);Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}finally{if(!shown)Hide();ShowInTaskbar=oldTaskbar;Bounds=oldBounds;SelectPage(oldPage);renderingPreview=false;}}
  void BuildSettings(){var p=NewPage();var config=new SurfacePanel();var rows=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=7,BackColor=Theme.Card};rows.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,158));rows.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));rows.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,158));rows.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));for(int i=0;i<7;i++)rows.RowStyles.Add(new RowStyle(SizeType.Absolute,54));intervalInput=Number(15,3600,controller.Settings.IntervalSeconds);timeoutInput=Number(3,20,controller.Settings.TimeoutSeconds);retentionInput=Number(1,90,controller.Settings.RetentionDays);adapterChoice=Combo(260);adapterChoice.Dock=DockStyle.Fill;notificationInput=Check("有情况时提醒我",controller.Settings.NotificationsEnabled);autoMonitorInput=Check("打开后自动后台检查",controller.Settings.AutoMonitor);aiAutoInput=Check("自动 GPT 分析（消耗额度）",controller.Settings.AiAutoEnabled);aiAnomalyInput=Check("有新情况就让 AI 看看",controller.Settings.AiOnAnomaly);aiIntervalInput=Number(5,1440,controller.Settings.AiIntervalMinutes);aiLimitInput=Number(0,200,controller.Settings.MaxAiCallsPerDay);codexPathInput=TextBoxDark(false);codexPathInput.BorderStyle=BorderStyle.FixedSingle;codexPathInput.Text=controller.Settings.CodexPath??"";codexPathInput.Dock=DockStyle.Fill;codexPathInput.Margin=new Padding(0,8,0,0);SettingRow(rows,0,"检查间隔（秒）",intervalInput,"等待回应（秒）",timeoutInput);SettingRow(rows,1,"保留记录（天）",retentionInput,"用网统计连接",adapterChoice);rows.Controls.Add(notificationInput,1,2);rows.Controls.Add(autoMonitorInput,3,2);rows.Controls.Add(aiAutoInput,1,3);rows.Controls.Add(aiAnomalyInput,3,3);SettingRow(rows,4,"AI 间隔（分钟）",aiIntervalInput,"AI 每日上限",aiLimitInput);rows.Controls.Add(LabelSized("Codex 路径",125),0,5);rows.Controls.Add(codexPathInput,1,5);rows.SetColumnSpan(codexPathInput,3);var hint=LabelText("自动分析发送匿名摘要；0 次上限将阻止全部 AI 调用。路径留空时自动查找 Codex。",8.5f,Theme.Muted,false);hint.Dock=DockStyle.Fill;rows.Controls.Add(hint,0,6);rows.SetColumnSpan(hint,4);config.Controls.Add(rows);Add(p,config,425);Note(p,"通知默认静音。最小化或关闭窗口后进入托盘并继续监测，托盘菜单可彻底退出。服务检测周期独立于本机流量采样；所有修改点击保存后生效。",54);var bar=Bar();var add=ButtonText("＋ 添加目标",false);add.Click+=delegate{if(targetGrid.Rows.Count>=64){MessageBox.Show(this,"最多保存 64 个目标。","目标数量");return;}int i=targetGrid.Rows.Add(true,"新目标","自定义","https://example.com/",Guid.NewGuid().ToString("N"));targetGrid.CurrentCell=targetGrid.Rows[i].Cells["name"];targetGrid.BeginEdit(true);};bar.Controls.Add(add);var remove=ButtonText("删除选中目标",false);remove.Width=140;remove.Click+=delegate{if(targetGrid.CurrentRow!=null)targetGrid.Rows.Remove(targetGrid.CurrentRow);};bar.Controls.Add(remove);var save=ButtonText("记住这些设置",true);save.Width=155;save.Click+=delegate{SaveSettings();};bar.Controls.Add(save);saveMessage=LabelSized("修改后点击保存",250);bar.Controls.Add(saveMessage);Add(p,bar,45);targetGrid=Grid(true);targetGrid.Columns.Add(new DataGridViewCheckBoxColumn{Name="enabled",HeaderText="要检查",FillWeight=65,MinimumWidth=65,SortMode=DataGridViewColumnSortMode.NotSortable});Col(targetGrid,"name","显示名称",165);Col(targetGrid,"group","分组",110);Col(targetGrid,"url","检测地址（不清楚可保留默认）",450);targetGrid.Columns.Add(new DataGridViewTextBoxColumn{Name="id",Visible=false});foreach(var t in controller.Settings.Targets)targetGrid.Rows.Add(t.Enabled,t.Name,t.Group,t.Url,t.Id);Add(p,TitledBox("想检查哪些网站和服务 · 可以编辑",targetGrid),430);Note(p,"只开启常用服务可减少后台请求。API 目标无密钥探测只检查网络与 HTTP 响应，不验证模型权限。请勿在 URL 中填入 API 密钥或其他凭据。",50);RefreshAdapterChoices();}
  CheckBox Check(string text,bool value){return new CheckBox{Text=text,Checked=value,ForeColor=Theme.Text,Dock=DockStyle.Fill};}
  NumericUpDown Number(int min,int max,int value){return new NumericUpDown{Minimum=min,Maximum=max,Value=Math.Max(min,Math.Min(max,value)),BackColor=Theme.Sidebar,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle,Width=110,Height=32,Margin=new Padding(0,7,12,0)};}
  void SettingRow(TableLayoutPanel p,int row,string a,Control b,string c,Control d){p.Controls.Add(LabelSized(a,125),0,row);p.Controls.Add(b,1,row);p.Controls.Add(LabelSized(c,125),2,row);p.Controls.Add(d,3,row);}
  void SaveSettings(){try{targetGrid.EndEdit();var targets=new List<ProbeTarget>();if(targetGrid.Rows.Count>64)throw new InvalidOperationException("最多保存 64 个检测目标。");foreach(DataGridViewRow row in targetGrid.Rows){string name=Convert.ToString(row.Cells["name"].Value).Trim(),url=Convert.ToString(row.Cells["url"].Value).Trim();Uri parsed;if(String.IsNullOrWhiteSpace(name))throw new InvalidOperationException("每个目标都需要显示名称。");if(!Uri.TryCreate(url,UriKind.Absolute,out parsed)||(parsed.Scheme!="https"&&parsed.Scheme!="http")||!String.IsNullOrEmpty(parsed.UserInfo))throw new InvalidOperationException("「"+name+"」需要有效的 HTTP / HTTPS 地址，不能含用户名密码。");targets.Add(new ProbeTarget{Id=String.IsNullOrWhiteSpace(Convert.ToString(row.Cells["id"].Value))?Guid.NewGuid().ToString("N"):Convert.ToString(row.Cells["id"].Value),Name=name,Group=Convert.ToString(row.Cells["group"].Value).Trim(),Url=url,Enabled=Convert.ToBoolean(row.Cells["enabled"].Value)});}var selected=adapterChoice.SelectedItem as Choice;var s=new AppSettings{IntervalSeconds=(int)intervalInput.Value,TimeoutSeconds=(int)timeoutInput.Value,RetentionDays=(int)retentionInput.Value,NotificationsEnabled=notificationInput.Checked,AutoMonitor=autoMonitorInput.Checked,TrafficAdapterId=selected==null?"auto":selected.Id,CodexPath=codexPathInput.Text.Trim(),AiAutoEnabled=aiAutoInput.Checked,AiOnAnomaly=aiAnomalyInput.Checked,AiIntervalMinutes=(int)aiIntervalInput.Value,MaxAiCallsPerDay=(int)aiLimitInput.Value,Targets=targets};controller.SaveSettings(s);saveMessage.Text="✓ 已保存  "+DateTime.Now.ToString("HH:mm:ss");saveMessage.ForeColor=Theme.Accent;RefreshHistoryChoices();RefreshData(true);}catch(Exception ex){ShowError(ex);}}
  class Choice{public string Id;public string Text;public Choice(string id,string text){Id=id;Text=text;}public override string ToString(){return Text;}}
  void RefreshAdapterChoices(){if(adapterChoice==null)return;var current=adapterChoice.SelectedItem as Choice;string wanted=current==null?controller.Settings.TrafficAdapterId:current.Id;adapterChoice.Items.Clear();adapterChoice.Items.Add(new Choice("auto","自动选择出口"));var local=controller.CurrentLocal;if(local!=null)foreach(var a in local.Adapters)adapterChoice.Items.Add(new Choice(a.Id,a.Name+(a.IsUp?"":" · 未连接")));int selected=0;for(int i=0;i<adapterChoice.Items.Count;i++)if(((Choice)adapterChoice.Items[i]).Id==wanted)selected=i;adapterChoice.SelectedIndex=selected;}
  void RefreshHistoryChoices(){if(historyMetric==null)return;var old=historyMetric.SelectedItem as Choice;string id=old==null?"traffic":old.Id;historyMetric.Items.Clear();historyMetric.Items.Add(new Choice("traffic","本机流量 · 下载 / 上传"));historyMetric.Items.Add(new Choice("gateway","网关响应延迟"));foreach(var t in controller.Settings.Targets)historyMetric.Items.Add(new Choice(t.Id,t.Name+" · HTTP 响应"));int selected=0;for(int i=0;i<historyMetric.Items.Count;i++)if(((Choice)historyMetric.Items[i]).Id==id)selected=i;historyMetric.SelectedIndex=selected;}
  TimeSpan SelectedPeriod(){switch(historyPeriod==null?0:historyPeriod.SelectedIndex){case 1:return TimeSpan.FromHours(6);case 2:return TimeSpan.FromHours(24);case 3:return TimeSpan.FromDays(7);case 4:return TimeSpan.FromDays(30);default:return TimeSpan.FromHours(1);}}
  void SelectPage(int index){bool enteringDevices=index==4&&activePage!=4;activePage=index;for(int i=0;i<pages.Count;i++)pages[i].Visible=i==index;pages[index].BringToFront();pageTitle.Text=titles[index];pageSubtitle.Text=subtitles[index];for(int i=0;i<navButtons.Count;i++){navButtons[i].BackColor=i==index?Theme.Translate(Color.FromArgb(32,62,70)):Theme.Sidebar;navButtons[i].ForeColor=i==index?Theme.Accent:Theme.Muted;navButtons[i].FlatAppearance.BorderColor=i==index?Color.FromArgb(43,104,102):Theme.Sidebar;}if(index==6)RefreshReport();if(index==7)RefreshAdapterChoices();RefreshData(true);if(enteringDevices&&Visible&&!renderingPreview){var passive=LoadDeviceRecordsAsync(true);}}
  void ControllerChanged(){if(IsDisposed||Disposing||!IsHandleCreated)return;if(InvokeRequired){if(updateQueued)return;updateQueued=true;try{BeginInvoke((Action)delegate{updateQueued=false;RefreshData(false);});}catch(InvalidOperationException){updateQueued=false;}}else RefreshData(false);}
