  void RefreshData(bool force){if(IsDisposed)return;if(activePage==6||force)RefreshQuotaView();var local=controller.CurrentLocal;var frame=controller.CurrentFrame;headerStatus.Text=controller.IsProbing?"● 正在检查":controller.IsMonitoring?"● 后台检查中":"● 已暂停";headerStatus.ForeColor=controller.IsMonitoring?Theme.Accent:Theme.Amber;pauseButton.Text=controller.IsMonitoring?"暂停后台":"恢复后台";if(local!=null){downloadCard.ValueText=local.TrafficRateReady?Theme.Rate(local.DownloadBps):"等待采样";downloadCard.Detail=PlainAdapterName(local.TrafficAdapterName)+" · 不是最高速度";uploadCard.ValueText=local.TrafficRateReady?Theme.Rate(local.UploadBps):"等待采样";uploadCard.Detail="电脑此刻用了多少上传";localSummary.Text="统计网卡  "+local.TrafficAdapterName+"     网关  "+(String.IsNullOrEmpty(local.Gateway)?"未识别":local.Gateway)+"     网关响应  "+Theme.Delay(frame==null?null:frame.GatewayMs)+"\n代理  "+(local.ProxySummary??"未读取")+"     最近采样  "+Theme.LocalTime(local.At);}var probes=frame==null?new List<ProbeResult>():frame.Probes??new List<ProbeResult>();var delays=probes.Where(x=>x.HttpMs.HasValue&&x.StatusCode.HasValue&&x.StatusCode!=407).Select(x=>x.HttpMs.Value).OrderBy(x=>x).ToList();latencyCard.ValueText=delays.Count==0?"—":Theme.Delay(delays.Count%2==1?delays[delays.Count/2]:(delays[delays.Count/2-1]+delays[delays.Count/2])/2);latencyCard.Detail=delays.Count==0?"等待第一次服务检查":"这次回应的典型等待时间";var findings=frame==null?new List<Finding>():frame.Findings??new List<Finding>();int issueCount=findings.Count(x=>IsAlert(x.Severity));int infoCount=findings.Count-issueCount;healthCard.ValueText=frame==null?"还没检查":issueCount==0?"未发现明显异常":issueCount.ToString()+" 项需留意";healthCard.Detail=frame==null?"完成检测后给出判读":"提示 "+infoCount+" 项 · "+(issueCount==0?"仍可打开应用试一试":"到检查页看看怎么做");healthCard.AccentColor=issueCount==0?Theme.Accent:Theme.Amber;foreach(var c in new[]{downloadCard,uploadCard,latencyCard,healthCard})c.Invalidate();checkStatus.Text=(controller.Status??"等待检测")+"\n"+(frame==null?"开始一次检测，获取网关、DNS、TCP 和 HTTP 证据。":"最近完整检测："+Theme.LocalTime(frame.At)+" · "+probes.Count+" 个目标");
   if(aiStatusLabel!=null){string tokens=controller.AiInputTokensToday<0||controller.AiOutputTokensToday<0||(controller.AiCallsToday>0&&controller.AiInputTokensToday==0&&controller.AiOutputTokensToday==0)?"实际 token 未返回":String.Format("已返回 token：输入 {0:N0} / 输出 {1:N0}",controller.AiInputTokensToday,controller.AiOutputTokensToday);aiStatusLabel.Text="本应用 · "+(controller.Settings.AiAutoEnabled?"自动 AI 已开启":"自动 AI 已关闭")+" · 今日 "+controller.AiCallsToday+" 次 / 上限 "+controller.Settings.MaxAiCallsPerDay+" · "+tokens+"\n"+(controller.AiStatus??"等待分析")+(controller.LastAiAt.HasValue?" · 最近 "+Theme.LocalTime(controller.LastAiAt.Value):"");if(aiButton!=null)aiButton.Enabled=!controller.IsAnalyzing;if(autoAiButton!=null){autoAiButton.Text=controller.Settings.AiAutoEnabled?"暂停自动 AI":"启用自动 AI";autoAiButton.BackColor=controller.Settings.AiAutoEnabled?Theme.Amber:Theme.Accent;autoAiButton.ForeColor=Theme.Back;}aiTopStatusLabel.Text=(controller.IsAnalyzing?"正在分析…":"本应用今日 "+controller.AiCallsToday+" 次")+(controller.LastAiAt.HasValue?" · "+controller.LastAiAt.Value.ToLocalTime().ToString("MM-dd HH:mm")+" 分析":" · 等待首次结果");RefreshAiResult();}
   if(force||DateTime.UtcNow-lastTablesPaint>TimeSpan.FromSeconds(3)){lastTablesPaint=DateTime.UtcNow;if(activePage==0)FillServices(probes);if(activePage==1)FillFindings(findingsGrid,findings,false);if(activePage==3)RefreshAdapters();if(activePage==4)RefreshDevices();if(activePage==5){var events=controller.Events;FillFindings(eventGrid,events,true);eventSummary.Text="已记录 "+events.Count+" 条事件 · 桌面通知"+(controller.Settings.NotificationsEnabled?"已开启":"静音")+" · 时间为本地时区";}}if(force||DateTime.UtcNow-lastHistoryPaint>TimeSpan.FromSeconds(3)){lastHistoryPaint=DateTime.UtcNow;if(activePage==0)RefreshLive();if(activePage==2)RefreshHistory();}RefreshPlainAnswers();if(floating!=null&&!floating.IsDisposed)floating.UpdateState(local,controller.IsMonitoring,issueCount);if(tray!=null)tray.Text="NetScope · "+(controller.IsMonitoring?"监测中":"已暂停")+(local==null?"":" ↓ "+(local.TrafficRateReady?Theme.Rate(local.DownloadBps):"等待采样"));}
  void RefreshPlainAnswers(){var frame=controller.CurrentFrame;var local=controller.CurrentLocal;var probes=frame==null?new List<ProbeResult>():frame.Probes??new List<ProbeResult>();var measured=probes.Where(x=>x.Outcome!="Skipped").ToList();var failed=measured.Where(x=>!x.StatusCode.HasValue||x.StatusCode==407).ToList();string names=String.Join("、",failed.Take(3).Select(x=>x.Name).ToArray());string connection=frame==null||measured.Count==0?"还没检查，暂时不知道现在顺不顺":failed.Count==0?"这次检查的 "+measured.Count+" 个网站都有回应":"这次检查：有 "+failed.Count+" 项暂时没收到回应";connectionSummary.Text=connection;connectionSummary.ForeColor=failed.Count==0?Theme.Accent:Theme.Amber;var slow=measured.Where(x=>x.StatusCode.HasValue&&x.HttpMs.HasValue&&x.HttpMs.Value>2000).ToList();slownessSummary.Text=frame==null?"点“检查现在为什么卡”，查看电脑、常用网站和 AI 服务。":failed.Count>0?"可能受影响："+names+"。一次没回应还不能确定原因。":slow.Count>0?"这次回应偏慢："+String.Join("、",slow.Take(3).Select(x=>x.Name).ToArray())+"。可再试一次你觉得卡的应用。":"目前没看到大范围断网的迹象；仍要结合实际应用体验。";uncertaintySummary.Text="仍不能确认：账号能否使用、应用内部是否顺畅，以及别的设备用了多少网。";if(answerHeadlines[0]==null)return;answerHeadlines[0].Text=frame==null?"还没有检查":measured.Count==0?"这轮没测到，暂时不能判断":failed.Count==0?"这次检查的 "+measured.Count+" 个网站都有回应":failed.Count+" 项暂时没回应";answerDetails[0].Text=frame==null?"点上方按钮，我会先检查电脑连接，再看看常用网站和 AI 服务。":failed.Count==0?"这不等于所有功能都能用。登录、账号权限和 AI 生成结果，还要在应用里确认。":"可能受影响："+names+"。只有这一次的结果，先别急着认定谁出了故障。";bool noConnection=local!=null&&!local.Adapters.Any(x=>x.IsUp);answerHeadlines[1].Text=frame==null||measured.Count==0?"还需要一次有效检查":noConnection?"电脑可能还没连上网":failed.Count==0?"这次没发现哪里连不上":"还不能锁定是哪一段";answerDetails[1].Text=noConnection?"先看看 Wi-Fi 或网线是否连好，再重新检查。":failed.Count>0?"可能与本机设置、中转工具或服务当时状态有关；需要更多次记录或换一个网络对比。":"本次结果只能反映这台电脑当时的连接，无法确认所有地方都正常。";if(speedCheckRunning){answerHeadlines[2].Text="正在测试下载速度…";answerDetails[2].Text="正在下载一小段测试内容，请稍候。这个结果不代表宽带最高速度。";}else if(lastSpeedTest!=null&&!String.IsNullOrWhiteSpace(lastSpeedTest.Error)){answerHeadlines[2].Text="这次测速没有完成";answerDetails[2].Text=FriendlyText(lastSpeedTest.Error)+"。可以稍后再试；这一次失败不能单独判断宽带问题。";}else if(lastSpeedTest!=null){answerHeadlines[2].Text=String.Format("小样本下载约 {0:0.0} Mbps",lastSpeedTest.Mbps);answerDetails[2].Text="测试时间 "+lastSpeedAt.ToString("HH:mm:ss")+"。这次只下载了一小段内容，不代表宽带最高速度或所有应用。";}else{answerHeadlines[2].Text=local==null||!local.TrafficRateReady?"还没有测速度":"当前下载用量 "+Theme.Rate(local.DownloadBps);answerDetails[2].Text="当前用量不是网速上限。要看这次下载快不快，可点下方做一次小流量测试。";}var gateway=controller.Devices.Where(x=>x.DownloadBps.HasValue&&x.ObservedAt.HasValue&&(x.Source??"").Contains("网关")).OrderByDescending(x=>x.DownloadBps.Value+(x.UploadBps??0)).FirstOrDefault();answerHeadlines[3].Text=gateway==null?"现在还查不到":"导入记录中："+DeviceFriendlyName(gateway);answerDetails[3].Text=gateway==null?"电脑的设备列表没有每台设备的用量。需要从路由器导出用网记录，再导入这里。":"这台设备在 "+Theme.LocalTime(gateway.ObservedAt.Value)+" 的记录较高；这是旧快照，不代表现在还在占网。";var traffic=controller.ProcessTraffic;var top=IsCurrentProcessSnapshot(traffic)&&traffic.Processes!=null?traffic.Processes.OrderByDescending(x=>x.DownloadBps+x.UploadBps).FirstOrDefault():null;answerHeadlines[4].Text=top==null?"现在还查不到":FriendlyNames.ProcessLabel(top.Name,top.Pid)+" 观测用量最多";answerDetails[4].Text=top==null?"需要你同意管理员权限，才能开启程序用网统计。普通模式的连接数量不能当作用量。":"下载 "+Theme.Rate(top.DownloadBps)+"，上传 "+Theme.Rate(top.UploadBps)+"。中转工具可能重复计数，不能据此断定某程序抢网。";if(traffic!=null&&traffic.LostEvents>0)answerDetails[4].Text+=" 本次统计不完整。";answerHeadlines[5].Text=frame==null?"先做一次检查":noConnection?"先连好 Wi-Fi 或网线":failed.Count>0?"先重试受影响的应用":"先试试刚才觉得卡的应用";answerDetails[5].Text=frame==null?"得到第一轮结果后，再决定要不要测速或让 AI 进一步解释。":failed.Count>0?"如果仍然不行，观察几分钟或换另一条网络对比；AI 可以结合记录给出更具体的下一步。":"如果应用仍卡，但检查都有回应，可能要继续查看账号、应用或程序用网情况。";checkStatus.Text=controller.IsProbing?"正在检查：电脑有没有联网 → 常用网站有没有回应 → AI 服务有没有回应\n正在收集结果，请稍候。":frame==null?"还没有检查。点下方按钮，我会回答这六个问题。":"已完成这轮检查 · "+Theme.LocalTime(frame.At)+"\n电脑联网 → 常用网站 → AI 服务。下面分别说明已知道什么、还查不到什么。";if(frame!=null&&measured.Count==0){answerDetails[0].Text="本轮检查没有取得可判断的结果；这不代表网络坏了，请稍后重试。";answerDetails[1].Text="没有有效检查结果，暂时不能判断是哪一段。";answerHeadlines[5].Text="稍等一下，再检查一次";answerDetails[5].Text="检查器可能正在忙，等这一轮结束后再试。";healthCard.ValueText="这轮还不能判断";healthCard.Detail="没有有效结果，请稍后再试";healthCard.Invalidate();}foreach(var label in answerHeadlines)label.ForeColor=Theme.Text;RefreshCheckHero();}
  void FillServices(List<ProbeResult> probes){serviceGrid.Rows.Clear();foreach(var target in controller.Settings.Targets.Where(t=>t.Enabled)){var r=probes.LastOrDefault(x=>x.TargetId==target.Id&&String.Equals(x.Url,target.Url,StringComparison.Ordinal));if(r==null){serviceGrid.Rows.Add(target.Name,target.Group,"还没有检查","启用后等待下一次检查。","—","—","—","—","—","—");continue;}int row=serviceGrid.Rows.Add(r.Name,r.Group,HumanStatus(r),HumanMeaning(r),Theme.Delay(r.DnsMs),Theme.Delay(r.TcpMs),Theme.Delay(r.HttpMs),r.Route,(r.StatusCode.HasValue?"HTTP "+r.StatusCode.Value+" · ":"")+r.Outcome,r.Error);serviceGrid.Rows[row].Tag=r;serviceGrid.Rows[row].Cells["status"].Style.ForeColor=r.Outcome=="Skipped"?Theme.Muted:r.StatusCode.HasValue?Theme.Accent:Theme.Amber;foreach(DataGridViewCell c in serviceGrid.Rows[row].Cells)c.ToolTipText=Convert.ToString(c.Value)+"\n双击展开完整说明。";}serviceGrid.ClearSelection();}
  bool IsAlert(string level){return new[]{"warning","warn","critical","error"}.Contains((level??"").ToLowerInvariant());}
  string Severity(string level){if(String.IsNullOrEmpty(level))return "提示";var x=level.ToLowerInvariant();if(x=="critical"||x=="error")return "严重";if(x=="warning"||x=="warn")return "注意";if(x=="info")return "提示";return level;}
  void FillFindings(DataGridView grid,List<Finding> items,bool withTime){grid.Rows.Clear();foreach(var f in items.OrderByDescending(x=>x.At)){int row=withTime?grid.Rows.Add(Theme.LocalTime(f.At),Severity(f.Severity),FriendlyText(f.Title),f.Evidence,FriendlyText(f.Advice)):grid.Rows.Add(Severity(f.Severity),FriendlyText(f.Title),f.Evidence,FriendlyText(f.Advice),f.Confidence);grid.Rows[row].Tag=f;grid.Rows[row].Cells[withTime?1:0].Style.ForeColor=IsAlert(f.Severity)?Theme.Amber:Theme.Muted;foreach(DataGridViewCell c in grid.Rows[row].Cells)c.ToolTipText=Convert.ToString(c.Value);}if(items.Count==0){if(withTime)grid.Rows.Add("—","—","尚无事件","采样后若规则发现异常，会记录在这里。","");else grid.Rows.Add("—","暂无发现","尚无异常证据，或还未完成首次检测。","可以点“检查现在为什么卡”。","—");}grid.ClearSelection();}
  List<ChartPoint> BreakGaps(List<ChartPoint> data,TimeSpan limit){var result=new List<ChartPoint>();ChartPoint prev=null;foreach(var point in data.OrderBy(x=>x.At)){if(prev!=null&&(point.At-prev.At>limit||!String.Equals(point.Segment,prev.Segment,StringComparison.Ordinal)))result.Add(new ChartPoint(prev.At.AddTicks((point.At-prev.At).Ticks/2),null));result.Add(point);prev=point;}return result;}
  List<ChartPoint> Reduce(List<ChartPoint> data,int max){if(data.Count<=max)return data;int step=(int)Math.Ceiling(data.Count/(double)max);var result=new List<ChartPoint>();for(int i=0;i<data.Count;i+=step){var chunk=data.Skip(i).Take(step).ToList();if(chunk.Any(x=>!x.Value.HasValue)){result.Add(chunk.First(x=>!x.Value.HasValue));continue;}var low=chunk.OrderBy(x=>x.Value).First();var high=chunk.OrderByDescending(x=>x.Value).First();if(low.At<=high.At){result.Add(low);if(high.At!=low.At)result.Add(high);}else{result.Add(high);result.Add(low);}}return result;}
  string NetworkKey(HistoryPoint p){return (p.TrafficAdapterId??"legacy-adapter")+"|"+(p.NetworkProfileId??"legacy-profile");}
  void RefreshLive(){DateTime end=DateTime.UtcNow;var data=controller.GetHistory(TimeSpan.FromMinutes(10)).Where(x=>x.Probes==null||x.Probes.Count==0).ToList();var d=new ChartSeries("下载",Theme.Accent);var u=new ChartSeries("上传",Theme.Blue);d.Points=Reduce(BreakGaps(data.Select(x=>new ChartPoint(x.At,x.DownloadBps,NetworkKey(x))).ToList(),TimeSpan.FromSeconds(75)),Math.Max(100,liveChart.Width));u.Points=Reduce(BreakGaps(data.Select(x=>new ChartPoint(x.At,x.UploadBps,NetworkKey(x))).ToList(),TimeSpan.FromSeconds(75)),Math.Max(100,liveChart.Width));liveChart.GapLimit=TimeSpan.FromSeconds(75);liveChart.UpdateData(new List<ChartSeries>{d,u},end.AddMinutes(-10),end,true);}
  void RefreshHistory(){if(historyPeriod==null||historyMetric==null)return;DateTime end=DateTime.UtcNow;TimeSpan period=SelectedPeriod();var data=controller.GetHistory(period);var choice=historyMetric.SelectedItem as Choice;string id=choice==null?"traffic":choice.Id;var series=new List<ChartSeries>();if(id=="traffic"){data=data.Where(x=>x.Probes==null||x.Probes.Count==0).ToList();var d=new ChartSeries("下载",Theme.Accent);var u=new ChartSeries("上传",Theme.Blue);d.Points=data.Select(x=>new ChartPoint(x.At,x.DownloadBps,NetworkKey(x))).ToList();u.Points=data.Select(x=>new ChartPoint(x.At,x.UploadBps,NetworkKey(x))).ToList();series.Add(d);series.Add(u);}else{var s=new ChartSeries(id=="gateway"?"网关响应":choice.Text,Theme.Accent);var target=controller.Settings.Targets.FirstOrDefault(x=>x.Id==id);foreach(var h in data.Where(x=>x.Probes!=null&&x.Probes.Count>0)){if(id=="gateway"){s.Points.Add(new ChartPoint(h.At,h.GatewayMs,NetworkKey(h)));continue;}var r=h.Probes.LastOrDefault(x=>x.TargetId==id&&target!=null&&String.Equals(x.Url,target.Url,StringComparison.Ordinal));s.Points.Add(new ChartPoint(r!=null&&r.At!=DateTime.MinValue?r.At:h.At,r!=null&&r.StatusCode.HasValue?r.HttpMs:null,NetworkKey(h)+"|"+(r==null?"missing":r.PathId??"legacy-path")));}series.Add(s);}foreach(var s in series)s.Points=Reduce(BreakGaps(s.Points,TimeSpan.FromSeconds(id=="traffic"?75:Math.Max(90,controller.Settings.IntervalSeconds*3))),Math.Max(180,historyChart.Width));historyChart.GapLimit=TimeSpan.FromSeconds(Math.Max(controller.Settings.IntervalSeconds*3,period.TotalSeconds/Math.Max(100,historyChart.Width)*4));historyChart.UpdateData(series,end-period,end,id=="traffic");}
  void RefreshAdapters(){if(adapterGrid==null)return;string selected=adapterGrid.CurrentRow==null?null:Convert.ToString(adapterGrid.CurrentRow.Tag);adapterGrid.Rows.Clear();var local=controller.CurrentLocal;if(local==null)return;foreach(var a in local.Adapters){int row=adapterGrid.Rows.Add(a.Name,a.IsUp?"已连接":"未连接",local.TrafficRateReady?Theme.Rate(a.DownloadBps):"等待采样",local.TrafficRateReady?Theme.Rate(a.UploadBps):"等待采样",a.Type+(a.IsVirtual?" · 虚拟":""),a.LinkMbps>0?a.LinkMbps.ToString("0")+" Mbps":"—",a.Addresses);adapterGrid.Rows[row].Tag=a.Id;if(a.Id==selected)adapterGrid.CurrentCell=adapterGrid.Rows[row].Cells[0];}RefreshAdapterDetail();}
  void RefreshAdapterDetail(){if(routeBox==null)return;var local=controller.CurrentLocal;if(local==null){routeBox.Text="等待网卡采样。";return;}string id=adapterGrid.CurrentRow==null?local.TrafficAdapterId:Convert.ToString(adapterGrid.CurrentRow.Tag);var a=local.Adapters.FirstOrDefault(x=>x.Id==id)??local.Adapters.FirstOrDefault();if(a==null){routeBox.Text="未发现可读取的网卡。";return;}routeBox.Text="网卡："+a.Name+"\r\n描述："+a.Description+"\r\n地址："+a.Addresses+"\r\nMAC："+a.Mac+"\r\n网关："+a.Gateways+"\r\nDNS："+a.DnsServers+"\r\n\r\n当前统计出口："+local.TrafficAdapterName+"\r\n代理设置："+local.ProxySummary+"\r\n\r\n每个 HTTP 目标的实际路由请看「实时总览」服务表。";}
  void RefreshDevices(){RefreshDiscoveryUi();if(deviceGrid==null)return;EnsureDeviceTopology(controller.Devices);RefreshProcessTraffic();string selectedKey=deviceGrid.CurrentRow!=null&&deviceGrid.CurrentRow.Selected?Convert.ToString(deviceGrid.CurrentRow.Cells["ip"].Value)+"|"+Convert.ToString(deviceGrid.CurrentRow.Cells["mac"].Value):null;deviceGrid.Rows.Clear();var devices=controller.Devices;foreach(var d in devices){int row=deviceGrid.Rows.Add(DeviceFriendlyName(d),String.IsNullOrWhiteSpace(d.Hint)||d.Hint=="未知"?"类型还未确认":d.Hint,DeviceNameConfidence(d),d.DownloadBps.HasValue?Theme.Rate(d.DownloadBps.Value):"还不知道",d.UploadBps.HasValue?Theme.Rate(d.UploadBps.Value):"还不知道",DeviceUnknownReason(d),d.Ip,d.Mac,d.State,d.ObservedAt.HasValue?Theme.LocalTime(d.ObservedAt.Value):"时刻未知",d.Source,d.ReportedName);deviceGrid.Rows[row].Tag=d;foreach(DataGridViewCell c in deviceGrid.Rows[row].Cells)c.ToolTipText=Convert.ToString(c.Value)+"\n双击查看完整设备信息。";}if(devices.Count==0)deviceGrid.Rows.Add("暂时没有设备记录","类型还未确认","还没有确认名字","还不知道","还不知道","点击上方重新看看","—","—","—","—","本机可见缓存","—");connectionGrid.Rows.Clear();foreach(var c in controller.Connections)connectionGrid.Rows.Add(c.ProcessName,c.Pid,c.LocalEndpoint,c.RemoteEndpoint,c.State);deviceGrid.ClearSelection();if(selectedKey!=null)foreach(DataGridViewRow row in deviceGrid.Rows)if(Convert.ToString(row.Cells["ip"].Value)+"|"+Convert.ToString(row.Cells["mac"].Value)==selectedKey){deviceGrid.CurrentCell=row.Cells[0];row.Selected=true;break;}connectionGrid.ClearSelection();RefreshFriendlyCards();}
    void EditDeviceLabel(){if(deviceGrid.CurrentRow==null||deviceGrid.SelectedRows.Count==0){MessageBox.Show(this,"先选择一台设备。","命名设备");return;}string mac=Convert.ToString(deviceGrid.CurrentRow.Cells["mac"].Value);string normalizedMac=System.Text.RegularExpressions.Regex.Replace(mac??"","[^0-9A-Fa-f]","");if(normalizedMac.Length!=12||normalizedMac=="000000000000"||normalizedMac.Equals("FFFFFFFFFFFF",StringComparison.OrdinalIgnoreCase)){MessageBox.Show(this,"该行没有 MAC 地址，暂时不能绑定本地名称。","命名设备");return;}var device=controller.Devices.FirstOrDefault(x=>String.Equals(x.Mac,mac,StringComparison.OrdinalIgnoreCase));using(var dialog=new Form{Text="给这台设备起名字",ClientSize=new Size(540,292),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=Theme.Back,ForeColor=Theme.Text,Font=Font}){var description=LabelText("仅匹配这个 MAC；同名不会自动推断为同一个人。\n名称留空将清除本地标签。",9,Theme.Muted,false);description.SetBounds(22,15,495,48);dialog.Controls.Add(description);var macLabel=LabelText("MAC  "+mac,10,Theme.Accent,true);macLabel.SetBounds(22,72,490,28);dialog.Controls.Add(macLabel);var nameLabel=LabelText("你想叫它什么",9,Theme.Muted,false);nameLabel.SetBounds(22,119,90,30);dialog.Controls.Add(nameLabel);var name=TextBoxDark(false);name.BorderStyle=BorderStyle.FixedSingle;name.MaxLength=80;name.SetBounds(120,119,390,30);name.Text=device==null?"":device.Name??"";dialog.Controls.Add(name);var typeLabel=LabelText("类型 / 我的备注",9,Theme.Muted,false);typeLabel.SetBounds(22,163,90,30);dialog.Controls.Add(typeLabel);var type=TextBoxDark(false);type.BorderStyle=BorderStyle.FixedSingle;type.MaxLength=80;type.SetBounds(120,163,390,30);type.Text=device==null?"":device.Hint??"";dialog.Controls.Add(type);var cancel=ButtonText("取消",false);cancel.DialogResult=DialogResult.Cancel;cancel.SetBounds(256,235,115,36);dialog.Controls.Add(cancel);var save=ButtonText("记住这个名字",true);save.DialogResult=DialogResult.OK;save.SetBounds(383,235,127,36);dialog.Controls.Add(save);dialog.AcceptButton=save;dialog.CancelButton=cancel;if(dialog.ShowDialog(this)==DialogResult.OK){try{controller.SetDeviceLabel(mac,name.Text.Trim(),type.Text.Trim());RefreshDevices();}catch(Exception ex){ShowError(ex);}}}}
  void RefreshReport(){if(reportBox==null)return;try{lastReport=controller.BuildReport(true);reportBox.Text=lastReport;if(aiInputBox!=null)aiInputBox.Text=String.IsNullOrWhiteSpace(controller.LastAiInput)?"尚无对应的分析输入记录。":controller.LastAiInput;}catch(Exception ex){reportBox.Text="暂时无法生成报告："+ex.Message;}}
  async Task RunCheck(){try{await controller.RunCheckAsync();RefreshData(true);}catch(Exception ex){ShowError(ex);}}
  void ShowError(Exception ex){MessageBox.Show(this,ex.Message,"NetScope",MessageBoxButtons.OK,MessageBoxIcon.Information);}
  void CopyText(string text){if(String.IsNullOrEmpty(text))return;try{Clipboard.SetText(text);}catch(Exception ex){ShowError(ex);}}
  void SaveDialog(string filter,string name,Action<string> save){using(var d=new SaveFileDialog{Filter=filter,FileName=name,OverwritePrompt=true}){if(d.ShowDialog(this)!=DialogResult.OK)return;try{save(d.FileName);MessageBox.Show(this,"已保存到：\n"+d.FileName,"NetScope");}catch(Exception ex){ShowError(ex);}}}
  void BuildTray(){tray=new NotifyIcon{Icon=Icon,Text="NetScope · 上网小助手",Visible=true};var menu=new ContextMenuStrip{BackColor=Theme.Card,ForeColor=Theme.Text};menu.Items.Add("打开上网小助手",null,delegate{RestoreMain();});menu.Items.Add("暂停 / 恢复后台记录",null,delegate{controller.SetMonitoring(!controller.IsMonitoring);RefreshData(true);});menu.Items.Add("检查现在为什么卡",null,async delegate{await RunCheck();});menu.Items.Add("显示 / 隐藏悬浮窗",null,delegate{ToggleFloat();});menu.Items.Add(new ToolStripSeparator());menu.Items.Add("退出 NetScope",null,delegate{exiting=true;Close();});tray.ContextMenuStrip=menu;tray.DoubleClick+=delegate{RestoreMain();};}
  void ToggleFloat(){if(floating==null||floating.IsDisposed){floating=new FloatingWindow(RestoreMain);var area=Screen.PrimaryScreen.WorkingArea;floating.Location=new Point(area.Right-floating.Width-22,area.Bottom-floating.Height-24);}if(floating.Visible)floating.Hide();else{floating.Show();RefreshData(false);}}
  void HideToTray(bool showFloat){Hide();if(showFloat&&(floating==null||floating.IsDisposed||!floating.Visible))ToggleFloat();if(firstHide&&controller.Settings.NotificationsEnabled){tray.BalloonTipTitle="NetScope 在后台运行";tray.BalloonTipText="双击悬浮窗或托盘图标恢复。托盘菜单可彻底退出。";tray.ShowBalloonTip(3000);}firstHide=false;}
  void RestoreMain(){Show();WindowState=FormWindowState.Normal;Activate();RefreshData(true);}
